size_t bit_index = 0;
size_t word_index = 0;
const size_t bits_per_word = sizeof(bitmap_t) * 8;
const size_t nwords = binfo->nbits / bits_per_word;

while (word_index < nwords) {
    bitmap_t word = bitmap[word_index];
    if (word != ~static_cast<bitmap_t>(0)) {
        // Find first unset bit in word
        while ((word & 1) != 0) {
            bit_index++;
            word >>= 1;
        }
        // Atomically set the bit
        bitmap_t mask = static_cast<bitmap_t>(1) << bit_index;
        bitmap_t old_word, new_word;
        do {
            old_word = bitmap[word_index];
            new_word = old_word | mask;
        } while (!std::atomic_compare_exchange_weak(&bitmap[word_index], &old_word, new_word));
        return word_index * bits_per_word + bit_index;
    }
    bit_index += bits_per_word;
    word_index++;
}

// If we reach here, all bits are set; return SIZE_MAX to indicate failure
return SIZE_MAX;

